/* Jornada do Caçador v62 — revisão final de estabilidade e segurança. */
(function(){
  const downloadJSON=(name,value)=>{const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)};

  function ensureCoverageDialog(){
    if(document.querySelector('#coverageDialog'))return;
    document.body.insertAdjacentHTML('beforeend',`<dialog id="coverageDialog"><div class="sectionHead"><div><div class="eyebrow">RELATÓRIO DE LEITURA</div><h2 id="coverageTitle">Cobertura do PDF</h2></div><button class="ghost" id="closeCoverage">Fechar</button></div><div id="coverageBody"></div><div class="modalActions"><button class="ghost" id="exportCoverage">Exportar relatório JSON</button></div></dialog>`);
    document.querySelector('#closeCoverage').onclick=()=>document.querySelector('#coverageDialog').close();
  }

  function coverageHTML(doc){
    const coverage=doc?.metadata?.coverage||{},plan=doc?.metadata?.analysis_plan||{},progress=doc?.metadata?.analysis_progress||{},detected=coverage.sections_detected||plan.sections?.map(x=>x.name)||[],covered=coverage.sections_covered||[],omissions=coverage.omissions||[],warnings=coverage.warnings||plan.warnings||[];
    return `<div class="card"><div class="syncCheck"><div><b>${Number(coverage.percent)||0}%</b><span>seções cobertas</span></div><div><b>${Number(coverage.summary_count)||0}</b><span>resumos criados</span></div><div><b>${Number(coverage.estimated_pages||plan.estimated_pages)||0}</b><span>páginas estimadas</span></div><div><b>${Math.round((Number(coverage.confidence)||0)*100)}%</b><span>confiança declarada</span></div></div><p><b>Etapa:</b> ${esc(progress.stage||'concluída')} · ${Number(progress.percent)||0}%</p></div><div class="card"><h3>Seções detectadas</h3>${detected.length?`<ol>${detected.map(x=>`<li>${esc(typeof x==='string'?x:x.name)}</li>`).join('')}</ol>`:'<p class="muted">Inventário ainda não disponível.</p>'}</div><div class="card"><h3>Seções declaradas como cobertas</h3>${covered.length?`<ul>${covered.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="muted">Nenhuma seção declarada.</p>'}</div>${omissions.length?`<div class="lessonBox trap"><b>Omissões informadas</b><ul>${omissions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${warnings.length?`<div class="lessonBox mnemonic"><b>Avisos para conferência</b><ul>${warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="lessonBox bizu"><b>✓ Nenhum alerta declarado</b>Mesmo assim, confira conteúdos decisivos no PDF original.</div>'}`;
  }

  window.openCoverageReport=function(id){ensureCoverageDialog();const doc=cloudDocuments.find(item=>item.id===id);if(!doc)return toast('Documento não encontrado');document.querySelector('#coverageTitle').textContent=doc.title;document.querySelector('#coverageBody').innerHTML=coverageHTML(doc);document.querySelector('#exportCoverage').onclick=()=>downloadJSON(`relatorio-cobertura-${doc.title.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`,{document_id:doc.id,title:doc.title,exported_at:new Date().toISOString(),metadata:doc.metadata});document.querySelector('#coverageDialog').showModal()};

  const baseDocumentCard=documentCard;
  documentCard=function(doc){
    let html=baseDocumentCard(doc),progress=doc.metadata?.analysis_progress;
    const stages={inventory:[1,'Mapeando o PDF'],generation:[2,'Gerando o conteúdo'],review:[3,'Revisando a qualidade'],completed:[4,'Conteúdo concluído']},stage=stages[progress?.stage]||[1,'Preparando a análise'],stageWidth=stage[0]*25;
    const extra=`${progress&&doc.processing_status==='processing'?`<div class="materialProgress"><div class="bar" role="progressbar" aria-valuemin="1" aria-valuemax="4" aria-valuenow="${stage[0]}" aria-label="${esc(stage[1])}"><div class="fill" style="width:${stageWidth}%"></div></div><div class="small muted"><b>Etapa ${stage[0]} de 4</b> — ${esc(stage[1])}</div></div>`:''}${doc.metadata?.coverage||doc.metadata?.analysis_plan?`<button class="ghost" data-coverage-doc="${doc.id}" style="width:100%;margin-top:8px">Ver relatório completo da análise</button>`:''}`;
    return html.replace('</article>',`${extra}</article>`);
  };
  const baseRenderUserDocuments=renderUserDocuments;
  renderUserDocuments=function(){baseRenderUserDocuments();document.querySelectorAll('[data-coverage-doc]').forEach(button=>button.onclick=()=>openCoverageReport(button.dataset.coverageDoc))};

  loadGeneratedContent=async function(){
    const campaign=activeCampaign();if(!cloudSession||!campaign?.dbId){ALL_SUMMARIES=[];ALL_FLASHCARDS=[];ALL_QUESTIONS=[];LEARNING_SUBJECTS=[];renderStudy();renderLearning();return}
    try{const response=await cloudFetch(`generated_study_content?campaign_id=eq.${campaign.dbId}&content_type=eq.summary&select=id,title,content,source_refs,source_document_id,approved&order=created_at.asc`),rows=await response.json();if(!response.ok)throw new Error(rows?.message||'Não foi possível carregar o conteúdo gerado.');const rawSubjects=rows.map(row=>row.content?.subject||'Conteúdo geral');migrateLearningSubjectKeys(rawSubjects);ALL_SUMMARIES=rows.map(row=>({id:row.id,documentId:row.source_document_id,title:row.title,source:row.content?.source||'PDF enviado',category:canonicalSubjectName(row.content?.subject),pageStart:Number(row.content?.page_start)||0,pageEnd:Number(row.content?.page_end)||0,approved:!!row.approved,explanation:row.content?.explanation||'',points:row.content?.points||[],example:row.content?.example||'',bizu:row.content?.bizu||'',mnemonic:row.content?.mnemonic||'',trap:row.content?.trap||''}));ALL_FLASHCARDS=rows.flatMap(row=>(row.content?.flashcards||[]).map(card=>[canonicalSubjectName(row.content?.subject),card.question,card.answer]));ALL_QUESTIONS=rows.flatMap(row=>(row.content?.questions||[]).filter(q=>Array.isArray(q.options)&&q.options.length===4&&Number.isInteger(q.correct_index)&&q.correct_index>=0&&q.correct_index<4).map(q=>({subject:canonicalSubjectName(row.content?.subject),topic:q.topic||row.title,statement:q.statement,options:q.options,correct_index:q.correct_index,explanation:q.explanation||'',difficulty:q.difficulty||'medio',origin:q.origin||'autoral'})));LEARNING_SUBJECTS=[...new Set([...ALL_SUMMARIES.map(x=>x.category),...ALL_FLASHCARDS.map(x=>x[0]),...ALL_QUESTIONS.map(x=>x.subject)])].sort((a,b)=>a.localeCompare(b,'pt-BR'));const rememberedTrail=libraryUI.trailSubject[state.activeCampaignId],wanted=canonicalSubjectName(rememberedTrail||selectedLearningSubject);selectedLearningSubject=LEARNING_SUBJECTS.find(subject=>subjectKey(subject)===subjectKey(wanted))||LEARNING_SUBJECTS[0]||'Conteúdo';libraryUI.trailSubject[state.activeCampaignId]=selectedLearningSubject;const savedSummary=libraryUI.summaryFilter[state.activeCampaignId]||'all',savedCard=libraryUI.cardFilter[state.activeCampaignId]||'all',summaryValue=savedSummary==='all'?'all':canonicalSubjectName(savedSummary),cardValue=savedCard==='all'?'all':canonicalSubjectName(savedCard),sf=$('#summaryFilter'),cf=$('#cardFilter'),ns=$('#noteSubject');sf.innerHTML='<option value="all">Todas as disciplinas</option>'+LEARNING_SUBJECTS.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sf.value=LEARNING_SUBJECTS.includes(summaryValue)?summaryValue:'all';cf.innerHTML='<option value="all">Todos os assuntos</option>'+LEARNING_SUBJECTS.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');cf.value=LEARNING_SUBJECTS.includes(cardValue)?cardValue:'all';ns.innerHTML='<option value="Geral">Geral</option>'+ALL_SUMMARIES.map(x=>`<option value="${esc(x.title)}">${esc(x.title)}</option>`).join('');saveLibraryUI();renderStudy();renderLearning();renderQuestionFilters()}catch(error){console.warn(error);toast('Não foi possível carregar o conteúdo gerado')}
  };

  window.setSummaryApproval=async function(id,approved){
    const item=ALL_SUMMARIES.find(summary=>summary.id===id);if(!item)return;
    try{const response=await cloudFetch(`generated_study_content?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({approved})});if(!response.ok)throw new Error('Não foi possível atualizar a conferência.');item.approved=approved;renderSummaries($('#summarySearch')?.value||'');toast(approved?'Conteúdo marcado como conferido por você.':'Conferência removida.')}catch(error){toast(error.message)}
  };

  window.openSummarySource=async function(id){const item=ALL_SUMMARIES.find(summary=>summary.id===id),doc=cloudDocuments.find(document=>document.id===item?.documentId);if(!doc)return toast('O PDF de origem não está disponível.');try{const url=await signedDocumentUrl(doc);window.open(`${url}#page=${Math.max(1,item.pageStart||1)}&view=FitH`,'_blank','noopener')}catch(error){toast(error.message)}};
  window.reportSummaryIssue=function(id){const item=ALL_SUMMARIES.find(summary=>summary.id===id);if(!item)return;const current=state.contentIssues?.[id]?.note||'',note=prompt('Descreva o possível erro ou ponto que precisa ser conferido:',current);if(note===null)return;state.contentIssues=state.contentIssues||{};if(note.trim())state.contentIssues[id]={note:note.trim(),title:item.title,source:item.source,campaignId:state.activeCampaignId,reported_at:new Date().toISOString()};else delete state.contentIssues[id];save();renderSummaries($('#summarySearch')?.value||'');toast(note.trim()?'Ponto marcado para conferência.':'Marcação removida.')};

  renderSummaries=function(query=''){
    const q=query.trim().toLocaleLowerCase('pt-BR'),filter=$('#summaryFilter')?.value||libraryUI.summaryFilter[state.activeCampaignId]||'all',items=ALL_SUMMARIES.filter(s=>{const hay=[s.title,s.category,s.explanation,s.example,s.bizu,s.mnemonic,s.trap,...(s.points||[])].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');return(filter==='all'||subjectKey(s.category)===subjectKey(filter))&&(!q||hay.includes(q))}),groups=items.reduce((out,item)=>{(out[item.category]||=[]).push(item);return out},{}),card=s=>`<article class="summaryCard"><button class="summaryHead" data-summary="${s.id}"><span class="summaryTitle"><span class="summaryMeta">${esc(s.source||'PDF enviado')} · ${s.approved?'✓ CONFERIDO PELO USUÁRIO':'GERADO POR IA'}${state.contentIssues?.[s.id]?' · ⚠ REVISAR':''}</span><span>${esc(s.title)}</span></span><span>＋</span></button><div class="summaryBody">${s.pageStart?`<span class="tag">Fonte: pág. ${s.pageStart}${s.pageEnd>s.pageStart?`–${s.pageEnd}`:''}</span>`:''}${s.explanation?`<p class="lessonIntro">${esc(s.explanation)}</p>`:''}<div class="lessonBox"><b>Pontos essenciais</b><ul>${(s.points||[]).map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>${s.example?`<div class="lessonBox"><b>Exemplo explicado</b>${esc(s.example)}</div>`:''}${s.bizu?`<div class="lessonBox bizu"><b>✓ Bizu de prova</b>${esc(s.bizu)}</div>`:''}${s.mnemonic?`<div class="lessonBox mnemonic"><b>◆ Mnemônico</b>${esc(s.mnemonic)}</div>`:''}${s.trap?`<div class="lessonBox trap"><b>⚠ Pegadinha frequente</b>${esc(s.trap)}</div>`:''}${state.contentIssues?.[s.id]?`<div class="lessonBox trap"><b>Ponto marcado para conferência</b>${esc(state.contentIssues[s.id].note)}</div>`:''}<div class="summaryActions">${s.documentId?`<button class="ghost" data-open-summary-source="${s.id}">Abrir PDF na página</button>`:''}<button class="ghost" data-approve-summary="${s.id}" data-approved="${s.approved?'1':'0'}">${s.approved?'Remover conferência':'Marcar como conferido'}</button><button class="ghost" data-report-summary="${s.id}">${state.contentIssues?.[s.id]?'Editar alerta':'Informar possível erro'}</button></div><p class="small muted">${s.approved?'Você registrou que conferiu este conteúdo.':'Conteúdo gerado por IA: confira o PDF original antes de decisões de estudo importantes.'}</p></div></article>`;$('#summaryList').innerHTML=items.length?`<div class="libraryFolders">${Object.entries(groups).sort(([a],[b])=>a.localeCompare(b,'pt-BR')).map(([subject,subjectItems])=>{const key=`study:${state.activeCampaignId}:${subjectKey(subject)}`,open=libraryUI.studyFolders[key]!==false;return`<section class="libraryFolder ${open?'open':''}" data-study-folder="${esc(key)}"><button class="folderHead" data-study-folder-toggle="${esc(key)}"><span><i>▤</i>${esc(subject)}</span><span class="tag">${subjectItems.length} resumo${subjectItems.length===1?'':'s'}</span></button><div class="folderBody">${subjectItems.map(card).join('')}</div></section>`}).join('')}</div>`:'<div class="empty">Nenhum resumo corresponde aos filtros. Envie um PDF na Biblioteca e gere o conteúdo.</div>';$$('[data-study-folder-toggle]').forEach(button=>button.onclick=()=>{const folder=button.closest('.libraryFolder'),open=!folder.classList.contains('open');folder.classList.toggle('open',open);libraryUI.studyFolders[button.dataset.studyFolderToggle]=open;saveLibraryUI()});$$('[data-summary]').forEach(b=>b.onclick=()=>{const summary=b.closest('.summaryCard');summary.classList.toggle('open');b.lastElementChild.textContent=summary.classList.contains('open')?'−':'＋'});$$('[data-open-summary-source]').forEach(button=>button.onclick=()=>openSummarySource(button.dataset.openSummarySource));$$('[data-report-summary]').forEach(button=>button.onclick=()=>reportSummaryIssue(button.dataset.reportSummary));$$('[data-approve-summary]').forEach(button=>button.onclick=()=>setSummaryApproval(button.dataset.approveSummary,button.dataset.approved!=='1'))
  };

  exportApplicationBackup=function(){downloadJSON(`jornada-cacador-backup-v62-${localDayKey()}.json`,{format:'jornada-cacador-backup',version:62,exported_at:new Date().toISOString(),campaign:activeCampaign(),state,documents:cloudDocuments.map(doc=>({id:doc.id,title:doc.title,document_type:doc.document_type,processing_status:doc.processing_status,detected_subject:doc.detected_subject,created_at:doc.created_at,metadata:doc.metadata})),study_content:{summaries:ALL_SUMMARIES,flashcards:ALL_FLASHCARDS,questions:ALL_QUESTIONS},notice:'Este backup não contém senhas, chaves secretas nem os arquivos PDF privados.'});toast('Backup completo da versão 62 exportado')};

  const baseDiagnostics=runSystemDiagnostics;
  runSystemDiagnostics=async function(){await baseDiagnostics();const root=$('#diagnosticsList'),ready=cloudDocuments.filter(x=>x.processing_status==='ready'),warnings=ready.filter(x=>x.metadata?.coverage?.needs_review),approved=ALL_SUMMARIES.filter(x=>x.approved).length,total=ALL_SUMMARIES.length,issues=Object.values(state.contentIssues||{}).filter(item=>item.campaignId===state.activeCampaignId).length;root.innerHTML=root.innerHTML.replace(/Versão (55|59|60|61)/g,'Versão 62');root.insertAdjacentHTML('beforeend',diagnosticRow('Cobertura pedagógica',warnings.length===0,`${ready.length} PDF(s) pronto(s) · ${warnings.length} com alerta de cobertura`)+diagnosticRow('Conferência humana',total===0||approved===total,`${approved} de ${total} resumo(s) marcados como conferidos · ${issues} alerta(s) do usuário`)+diagnosticRow('Limite diário de PDFs',true,'Até 10 análises concluídas; tentativas com erro não são cobradas'))};

  ensureCoverageDialog();
  document.querySelector('#aboutDialog .tag').textContent='Versão 62 · Revisão final de estabilidade e segurança';
  document.querySelector('#diagnosticsDialog .small.muted').textContent='Versão 62 · foco, cobertura, consumo, segurança e sincronização';
  setInterval(()=>{if(document.visibilityState==='visible'&&cloudSession&&cloudDocuments.some(doc=>doc.processing_status==='processing'))loadCloudDocuments()},10000);
})();
